{
  "technical_and_design_decisions": [
    "Use Scala for Spark streaming and batch job modules as per U1 and U8.",
    "Adopt testcontainers library to manage external Kafka broker for integration tests (U4, U6).",
    "Modify publish-maven.gradle to read dependency versions from dependencies.properties using Gradle's property API (U5).",
    "Update log pattern in xd-container-logger.properties to include ISO8601 date format (U3).",
    "SonarQube violations will be addressed by fixing code for relevant issues and marking irrelevant ones as 'Won't Fix' or 'False Positive' in SonarQube UI (U7).",
    "Spark streaming module will be packaged as a Spring XD module with a modules.yml descriptor (U1).",
    "Spark batch job sample will be a standalone Scala application demonstrating distributed computation, optionally packaged as a Spring XD module (U8)."
  ],
  "assumptions": [
    "Developer has full access to the Spring XD 1.1.0.SNAPSHOT codebase and build environment.",
    "Wiki is part of the project repository (e.g., GitHub wiki) and can be updated via markdown files.",
    "xd-container-logger.properties exists at config/xd-container-logger.properties and uses Log4j pattern layout.",
    "publish-maven.gradle and dependencies.properties are located in the project root or known Gradle script directory.",
    "SonarQube server is already configured for the project and accessible.",
    "External Kafka broker for tests can be run via Docker containers (testcontainers) without requiring separate infrastructure.",
    "Spark and Kafka versions are compatible with Spring XD 1.1.0 and Java 17+.",
    "The Spark batch job sample is a simple demonstration (e.g., word count) and not a full production-grade job.",
    "All changes will be submitted via pull requests and undergo code review."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Spark Streaming Module Deployment",
      "activity_description": "Design and implement a Spark streaming module in Scala, create module descriptor (modules.yml), test deployment in local Spring XD environment, and document deployment steps.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Wiki Update for ulimit Setting",
      "activity_description": "Add a Troubleshooting section to the project wiki with recommended ulimit setting of 10K for XD distributed setup, including the exception context from U2.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "Logging Date Configuration",
      "activity_description": "Modify xd-container-logger.properties to include date in log pattern (e.g., ISO8601 format) and verify logs show date in container output.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A4",
      "activity_name": "Kafka Tests with External Broker",
      "activity_description": "Refactor Kafka integration tests to use an external Kafka broker via testcontainers, configure Gradle to manage broker lifecycle, update existing tests, and verify reduced build footprint and improved experience (covers U4 and U6).",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A5",
      "activity_name": "Publish Maven Gradle Script Update",
      "activity_description": "Update publish-maven.gradle to read Spring Boot and hadoop-common dependency versions from dependencies.properties, replacing hardcoded values, and test publishing to local Maven repository.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A6",
      "activity_name": "Sonar Violations Review and Fix",
      "activity_description": "Run SonarQube analysis, triage violations, fix relevant code issues, mark irrelevant violations as false positive or won't fix in SonarQube, and commit changes.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7",
      "activity_name": "Spark Batch Job Sample",
      "activity_description": "Design and implement a sample Spark batch job (e.g., word count) in Scala, package as a Spring XD module or standalone demo, document, and test to demonstrate distributed data computation capabilities.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A8",
      "activity_name": "Cross-cutting Code Review and Integration Testing",
      "activity_description": "Conduct peer code reviews for all changes, perform integration testing of all features together, and verify build and release readiness.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 71
  }
}

